#!/usr/bin/env python3
"""Build a self-contained interactive Duo demo around the actual browser app."""
from pathlib import Path
import json
import re
root=Path(__file__).resolve().parents[1]
# The wrapper follows the app's gallery, so new visualizers never go stale here.
styles=re.search(r"^const styles=\[(.*)\];$",(root/'Web/app.js').read_text(),re.M).group(1)
visual_ids=re.findall(r"\['(\w+)','",styles)
assert len(visual_ids)>=3,'Could not read visualizer ids from Web/app.js'
app=json.dumps((root/'Preview.html').read_text()).replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Afterglow · Open up your atmosphere</title><style>
:root{color-scheme:dark;--ink:#eef1f9;--muted:#949caf;--accent:#bac3ff}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#080c14;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100dvh;background-image:radial-gradient(ellipse at 75% 45%,#26375466,transparent 55%)}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid #bac3ff;outline-offset:4px}header{height:100px;padding:28px 5vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff0b}.brand{font-size:25px;letter-spacing:-1px}.brand b{color:#aab6ff;margin-right:10px;font-size:36px;font-weight:300}header small,.eyebrow{font:10px ui-monospace,monospace;letter-spacing:2.5px;color:var(--muted)}main{display:grid;grid-template-columns:minmax(280px,.72fr) minmax(0,1.28fr);align-items:center;max-width:1520px;margin:auto;min-height:calc(100dvh - 172px);padding:40px 5vw;gap:25px}.copy h1{font-size:clamp(44px,4.5vw,74px);line-height:1.05;letter-spacing:-3px;font-weight:400;margin:24px 0}.copy h1 span{color:var(--accent)}.copy p{color:#a4aec0;font-size:15px;line-height:1.8;max-width:335px}.pose-controls{display:flex;flex-wrap:wrap;gap:7px;margin:28px 0 20px}.pose-controls button{background:#111926;border:1px solid #ffffff15;border-radius:10px;padding:12px 16px;font-size:12px;min-height:44px}.pose-controls button[aria-pressed=true]{color:#c3cbff;border-color:#a6b5ff70;background:#25304b}.scenes{display:flex;gap:18px;margin:22px 0 28px}.scenes button{border:0;background:none;font-size:11px;padding:10px 0;color:#a6b1c6}.scenes button[aria-pressed=true]{color:#fff;border-bottom:1px solid #b6c1ff}.tour{background:#d4dcff;color:#151b2d;border:0;padding:14px 20px;border-radius:12px;font-size:12px;font-weight:600}.caption{margin:16px 0;font-size:10px!important;color:#68768e!important;line-height:1.6!important}.stage{min-width:0;height:595px;display:flex;align-items:center;justify-content:center;perspective:1600px;position:relative}.aura{position:absolute;inset:90px 10% 30px;background:#92a4ff0a;filter:blur(50px);border-radius:50%}.device{--w:890;--h:626;--scale:.7;box-sizing:content-box;width:calc(var(--w)*var(--scale)*1px);height:calc(var(--h)*var(--scale)*1px);padding:10px;background:linear-gradient(120deg,#7d8595,#2b3341 8%,#080c14 48%,#77818e 95%,#1c2431);border-radius:30px;box-shadow:0 45px 70px #0009,0 0 0 1px #ffffff33,inset 0 0 0 3px #ffffff12;position:relative;transition:width .8s cubic-bezier(.2,.8,.2,1),height .8s cubic-bezier(.2,.8,.2,1),transform .8s}.screen{position:relative;overflow:hidden;width:100%;height:100%;border-radius:22px;background:#090b13}.screen iframe{position:absolute;left:0;top:0;border:0;width:calc(var(--w)*1px);height:calc(var(--h)*1px);transform:scale(var(--scale));transform-origin:0 0;background:#090b13}.device[data-pose=tabletop]{transform:rotateX(13deg) rotateY(-4deg)}.hinge{position:absolute;top:50%;left:10px;right:10px;height:7px;background:linear-gradient(#0001,#0008,#ffffff0a);opacity:0;pointer-events:none}.device[data-pose=tabletop] .hinge{opacity:.8}.pose-label{position:absolute;bottom:0;width:100%;text-align:center;color:#6e7d94;font:9px ui-monospace,monospace;letter-spacing:2px}footer{min-height:72px;padding:18px 5vw;border-top:1px solid #ffffff0b;display:flex;justify-content:space-between;gap:20px;font-size:10px;line-height:1.6;color:#77859d}footer span:first-child{color:#a3b1c8}.tour-progress{width:100%;position:fixed;bottom:0;left:0;height:2px;background:#bac3ff;transform:scaleX(0);transform-origin:left;z-index:20}@media(max-width:1000px){header{height:78px}main{grid-template-columns:1fr;padding-top:30px}.copy{text-align:center}.copy h1{font-size:48px}.copy p{margin:auto;max-width:500px}.copy br{display:none}.pose-controls,.scenes{justify-content:center}.stage{height:560px}.caption{margin:14px auto!important}footer{flex-direction:column}}@media(max-width:520px){header small{display:none}.copy h1{font-size:42px;letter-spacing:-2px}.stage{height:490px}main{padding:28px 16px;gap:15px}.pose-controls button{padding:12px}.scenes{gap:25px}}@media(prefers-reduced-motion:reduce){.device{transition:none}}
</style></head><body><header><div class="brand"><b>≋</b>afterglow</div><small>IPHONE DUO · INTERACTIVE PREVIEW</small></header><main><section class="copy"><div class="eyebrow">MORE ROOM TO FEEL.</div><h1>Open up<br> your <span>atmosphere.</span></h1><p id="description" aria-live="polite">Unfold a bigger view. Keep your music and visual controls beside the scenery.</p><div class="pose-controls" aria-label="Device layout"><button data-pose="closed" aria-pressed="false">01 · Closed</button><button data-pose="open" aria-pressed="true">02 · Open</button><button data-pose="tabletop" aria-pressed="false">03 · Tabletop</button></div><div class="scenes" aria-label="Choose a visualizer"><button data-visual="yosemite" aria-pressed="true">YOSEMITE</button><button data-visual="aurora" aria-pressed="false">AURORA</button><button data-visual="orbit" aria-pressed="false">ORBIT</button></div><button class="tour" id="tour">▶ Play the 20-second tour</button><p class="caption">Everything inside the screen is interactive.<br>Import a track in the app to add your own soundtrack.</p></section><section class="stage" id="demo-stage" aria-label="Interactive device frame"><div class="aura"></div><div class="device" id="device" data-pose="open"><div class="screen"><iframe id="app" title="Afterglow live interactive preview" allow="autoplay; microphone"></iframe></div><div class="hinge"></div></div><div class="pose-label" id="pose-label">OPEN · EXPANDED STUDIO</div></section></main><footer><span>__VISUAL_COUNT__ visualizers. 5 palettes. One uninterrupted session.</span><span>Illustrative device frame and simulated poses. Browser app, not an iOS Simulator recording.</span></footer><div class="tour-progress" id="progress"></div><script>
const app=document.getElementById('app'),device=document.getElementById('device'),stage=document.getElementById('demo-stage');
const descriptions={closed:'A quieter pocket of the world. Your visualizer, music, and quick controls fit the outer display.',open:'Unfold a bigger view. Keep your music and visual controls beside the scenery.',tabletop:'Set it down. Scenery above, controls within reach below. A small listening room, anywhere.'};
const labels={closed:'CLOSED · POCKET STUDIO',open:'OPEN · EXPANDED STUDIO',tabletop:'TABLETOP · SCENE + CONTROL DECK'};
let pose='open',visual='yosemite',loaded=false,tourStart=null,tourFrame=null;
function send(includeVisual=false){if(loaded)app.contentWindow.postMessage({type:'afterglow-duo-demo',pose,...(includeVisual?{visual}:{})},'*')}
function fit(){const w=pose==='closed'?466:890,h=pose==='closed'?678:626;const scale=Math.max(.2,Math.min(pose==='closed'?.76:.82,(stage.clientWidth-30)/w,(stage.clientHeight-55)/h));device.style.setProperty('--w',w);device.style.setProperty('--h',h);device.style.setProperty('--scale',scale)}
function choosePose(value){pose=value;device.dataset.pose=pose;document.getElementById('description').textContent=descriptions[pose];document.getElementById('pose-label').textContent=labels[pose];document.querySelectorAll('[data-pose]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',b.dataset.pose===pose)});fit();send()}
function chooseVisual(value){visual=value;document.querySelectorAll('[data-visual]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.visual===visual));send(true)}
function stopTour(){if(tourFrame!==null)cancelAnimationFrame(tourFrame);tourFrame=null;tourStart=null;document.getElementById('tour').textContent='▶ Replay the 20-second tour';document.getElementById('progress').style.transform='scaleX(0)'}
document.querySelectorAll('button[data-pose]').forEach(b=>b.onclick=()=>{stopTour();choosePose(b.dataset.pose)});document.querySelectorAll('[data-visual]').forEach(b=>b.onclick=()=>{stopTour();chooseVisual(b.dataset.visual)});
function tour(now){if(tourStart===null)tourStart=now;const t=(now-tourStart)/1000;const next=t<5?'closed':t<11?'open':t<17?'tabletop':'open',scene=t<17?'yosemite':'aurora';if(next!==pose)choosePose(next);if(scene!==visual)chooseVisual(scene);document.getElementById('progress').style.transform='scaleX('+Math.min(1,t/20)+')';if(t<20)tourFrame=requestAnimationFrame(tour);else stopTour()}
document.getElementById('tour').onclick=()=>{if(tourFrame!==null){stopTour();return}document.getElementById('tour').textContent='Ⅱ Stop tour';tourFrame=requestAnimationFrame(tour)};
window.addEventListener('message',event=>{if(event.source===app.contentWindow&&event.data?.type==='afterglow-demo-state'&&__VISUAL_IDS__.includes(event.data.visual)){visual=event.data.visual;document.querySelectorAll('[data-visual]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.visual===visual))}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour()});window.addEventListener('resize',fit);app.onload=()=>{loaded=true;send()};
app.srcdoc=APP_SOURCE;fit();
</script></body></html>'''
page=page.replace('__VISUAL_COUNT__',str(len(visual_ids))).replace('__VISUAL_IDS__',json.dumps(visual_ids,separators=(',',':')))
(root/'Duo-Demo.html').write_text(page.replace('APP_SOURCE',app))
print('Built Duo-Demo.html using the actual Preview.html in one persistent iframe.')
